// ── 1) interface مقابل type alias ─────────────────────────────────────
// interface: للكائنات اللي ممكن تتوسّع (declaration merging) — مثل عقود الـAPI
export interface Order {
  readonly id: string;
  readonly customerId: string;
  readonly total: string;        // المال نص (decimal) — لا number (كل الأرقام double)
  readonly currency: "EGP" | "USD";
  readonly status: OrderStatus;
  readonly placedAt: string;     // ISO 8601 من الخادم
  readonly items: readonly OrderItem[];   // readonly يمنع إعادة التعيين فقط
}

export interface OrderItem {
  readonly sku: string;
  readonly name: string;
  readonly qty: number;
  readonly unitPrice: string;    // decimal كنص
}

// type alias: للاتحادات والدوال والأنواع المشتقة
export type OrderStatus = "draft" | "placed" | "paid" | "shipped" | "cancelled";
export type OrderId = string & { readonly __brand: "OrderId" };  // nominal typing خفيف

// ── 2) الحالات كـdiscriminated union (أقوى نمط في الواجهة — 8.1.4) ────
export type Remote<T> =
  | { readonly kind: "idle" }
  | { readonly kind: "loading" }
  | { readonly kind: "error"; readonly error: ApiError }
  | { readonly kind: "success"; readonly data: T };

// ── 3) أخطاء موحدة مطابقة لـProblemDetails (RFC 9457 / 2.2.3) ─────────
export interface ApiError {
  readonly status: number;                 // 0 = شبكة
  readonly title: string;
  readonly detail?: string;
  readonly type?: string;
  readonly instance?: string;
  readonly correlationId?: string;         // للربط بالسجلات (7.1.3)
  readonly fieldErrors?: Readonly<Record<string, readonly string[]>>;
  readonly retryAfterSeconds?: number;     // من 429
}

// ── 4) generics مع قيود (زي where T : class في C#) ─────────────────────
export interface Page<T> {
  readonly items: readonly T[];
  readonly nextCursor?: string | null;     // cursor pagination (2.2.2)
}

export function firstOf<T>(items: readonly T[]): T | undefined {
  return items[0];
}

// ── 5) أنواع مشتقة من البيانات (تقليل التكرار) ─────────────────────────
export type OrderDto = Omit<Order, "items"> & { items: OrderItem[] };
export type OrderPatch = Partial<Pick<OrderDto, "status" | "items">>;
export type StatusLabels = Record<OrderStatus, string>;

// ── 6) تضييق الأنواع (narrowing) بدل أي cast ───────────────────────────
export function isApiError(value: unknown): value is ApiError {
  return (
    typeof value === "object" &&
    value !== null &&
    "status" in value &&
    typeof (value as { status?: unknown }).status === "number"
  );
}

// ── 7) satisfies: تحقق من الشكل من غير توسيع النوع ─────────────────────
export const statusLabels = {
  draft: "مسودة",
  placed: "تم الطلب",
  paid: "مدفوع",
  shipped: "تم الشحن",
  cancelled: "ملغي",
} satisfies StatusLabels;      // خطأ إملائي في مفتاح = خطأ ترجمة فورًا

import type { ApiError, Order, Page } from "./types";

const BASE = import.meta.env.VITE_API_BASE ?? "/api";

/**
 * مقابل HttpClient في .NET — بس بأخطاء واضحة وإلغاء صريح.
 * القواعد:
 *   • fetch لا يرمي على 4xx/5xx — لازم تفحص res.ok بنفسك.
 *   • الإلغاء/المهلة عبر AbortSignal (مقابل CancellationToken).
 *   • لا نثق في النوع: نتحقق من الشكل قبل الإرجاع (8.1.1 ③).
 */
export async function listOrders(
  cursor: string | null,
  options: { signal?: AbortSignal; timeoutMs?: number } = {},
): Promise<Page<Order>> {
  const { signal, timeoutMs = 8_000 } = options;

  // جمع إشارة المستخدم مع مهلة الطلب (مثل CancellationTokenSource.CreateLinkedTokenSource)
  const combined = signal
    ? AbortSignal.any([signal, AbortSignal.timeout(timeoutMs)])
    : AbortSignal.timeout(timeoutMs);

  // نبني الاستعلام بـURLSearchParams (لا ندمج نصوصًا يدويًا — 2.2.1)
  const qs = new URLSearchParams({ limit: "20" });
  if (cursor) qs.set("cursor", cursor);

  let res: Response;
  try {
    res = await fetch(`${BASE}/orders?${qs}`, {
      method: "GET",
      headers: { Accept: "application/json" },
      credentials: "include",          // كوكيز الجلسة في نمط BFF (8.1.2)
      signal: combined,
    });
  } catch (err) {
    throw toNetworkError(err);         // شبكة/مهلة/إلغاء — لا HTTP
  }

  if (!res.ok) {
    throw await toApiError(res);       // 4xx/5xx → خطأ موحّد
  }

  const body: unknown = await res.json();
  return parsePage(body);
}

/** يحوّل استجابة غير ناجحة إلى ApiError من ProblemDetails (2.2.3). */
async function toApiError(res: Response): Promise<ApiError> {
  const correlationId = res.headers.get("X-Correlation-Id") ?? undefined;
  const retryAfter = res.headers.get("Retry-After");

  let body: unknown = undefined;
  try {
    body = await res.json();
  } catch {
    // جسم غير JSON (وسيط/بوابة) — نتعامل مع الحالة وحدها
  }

  const pd = (typeof body === "object" && body !== null ? body : {}) as Record<string, unknown>;
  return {
    status: res.status,
    title: typeof pd.title === "string" ? pd.title : defaultTitle(res.status),
    detail: typeof pd.detail === "string" ? pd.detail : undefined,
    type: typeof pd.type === "string" ? pd.type : undefined,
    instance: typeof pd.instance === "string" ? pd.instance : undefined,
    correlationId: (typeof pd.instance === "string" ? pd.instance : undefined) ?? correlationId,
    fieldErrors: extractFieldErrors(pd.errors),
    retryAfterSeconds: retryAfter ? Number.parseInt(retryAfter, 10) || undefined : undefined,
  };
}

function extractFieldErrors(errors: unknown): Record<string, readonly string[]> | undefined {
  if (typeof errors !== "object" || errors === null) return undefined;
  const out: Record<string, string[]> = {};
  for (const [field, messages] of Object.entries(errors as Record<string, unknown>)) {
    out[field] = Array.isArray(messages)
      ? messages.filter((m): m is string => typeof m === "string")
      : [];
  }
  return out;
}

function toNetworkError(err: unknown): ApiError {
  const isTimeout = err instanceof DOMException && err.name === "TimeoutError";
  const isAbort = err instanceof DOMException && err.name === "AbortError";
  return {
    status: 0,
    title: isAbort ? "أُلغي الطلب" : isTimeout ? "انتهت مهلة الاتصال" : "تعذر الوصول إلى الخادم",
    detail: isAbort || isTimeout ? undefined : "تحقق من الاتصال بالإنترنت ثم أعد المحاولة.",
  };
}

function defaultTitle(status: number): string {
  if (status === 401) return "انتهت الجلسة — سجّل الدخول مرة أخرى";
  if (status === 403) return "ليس لديك صلاحية لهذا الإجراء";
  if (status === 404) return "العنصر غير موجود";
  if (status === 409) return "تعارض مع حالة أحدث — حدّث البيانات";
  if (status === 429) return "عدد كبير من الطلبات — حاول بعد قليل";
  if (status >= 500) return "خطأ في الخادم";
  return `طلب غير ناجح (${status})`;
}

/**
 * تحقق وقت التشغيل من شكل الصفحة (الأنواع بتتمسح — 8.1.1 ③).
 * اصطلاح المشروع: نرمي كائن ApiError (لا Error) عشان الواجهة تتعامل مع
 * كل الفشل بشكل واحد — وده يتطلب isApiError() في كل catch (ضيق النوع أولًا).
 */
function parsePage(body: unknown): Page<Order> {
  if (typeof body !== "object" || body === null || !Array.isArray((body as { items?: unknown }).items)) {
    throw { status: 0, title: "استجابة غير متوقعة من الخادم" } satisfies ApiError;
  }
  return body as Page<Order>;
}
